//! Raytracer benchmark in cuda-oxide, mirroring the rust-gpu DSL version in
//! examples/src/benchmarks/raytracer.rs as closely as the API allows:
//!
//! - same scene: 20 spheres generated by the same LCG (`rnd`) as the Elixir
//!   reference and the DSL port, same per-dim radius/sum table
//! - same math: per-pixel loop over all 20 spheres, nearest hit wins, f32
//!   throughout
//! - same launch geometry: 16x16 thread blocks over a (dim x dim) image
//! - same buffer: dim*dim RGBA pixels (one float4-layout `Rgba` per pixel, as
//!   in the julia/ripple ports, instead of 4 flat f32)
//! - same measured region: device alloc + H2D upload, kernel, D2H readback
//!
//! Prints the `[raytracer] elapsed: X ms` line bench_runs.sh parses.
//!
//! Build with `cargo oxide build` (not plain cargo); run as `raytracer <dim>`.

use std::time::Instant;

use cuda_core::{CudaContext, DeviceBuffer, LaunchConfig};
use cuda_host::cuda_module;

/// One RGBA pixel with CUDA `float4` layout, as in the julia/ripple ports.
#[repr(C, align(16))]
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Rgba(pub [f32; 4]);

unsafe impl cuda_core::DeviceCopy for Rgba {}

/// Simple LCG matching the seed/range from the Elixir reference and the DSL
/// port: rnd(x) = x * randint(1, 32767) / 32767.
fn rnd(x: f32, state: &mut u32) -> f32 {
    *state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
    let v = ((*state >> 1) % 32767) + 1;
    x * v as f32 / 32767.0
}

/// 20 spheres, 7 f32 fields each: r, g, b, radius, x, y, z. Same LCG stream
/// and per-dim radius/sum table as the DSL's `generate_spheres`.
fn generate_spheres(dim: usize) -> Vec<f32> {
    let (radius, sum) = match dim {
        256 => (20.0f32, 5.0f32),
        1024 => (80.0f32, 20.0f32),
        2048 => (120.0f32, 20.0f32),
        _ => (160.0f32, 20.0f32),
    };

    let mut state: u32 = 313;
    let mut spheres = Vec::with_capacity(20 * 7);
    for _ in 0..20 {
        spheres.push(rnd(1.0, &mut state)); // r
        spheres.push(rnd(1.0, &mut state)); // g
        spheres.push(rnd(1.0, &mut state)); // b
        spheres.push(rnd(radius, &mut state) + sum); // radius
        spheres.push(rnd(dim as f32, &mut state) - dim as f32 / 2.0); // x
        spheres.push(rnd(dim as f32, &mut state) - dim as f32 / 2.0); // y
        spheres.push(rnd(256.0, &mut state) - 128.0); // z
    }
    spheres
}

#[cuda_module]
mod kernels {
    use super::Rgba;
    use cuda_device::thread::Runtime2DIndex;
    use cuda_device::{DisjointSlice, kernel, thread};

    /// One pixel per thread. `image`'s runtime row width carries the square
    /// image dimension, so (unlike the DSL kernel) no separate width/height
    /// parameters are needed: a witness only exists for in-grid threads, and
    /// `spheres` stays a plain read-only slice since every thread reads the
    /// same 20 spheres in full.
    #[kernel]
    pub fn raytracing(spheres: &[f32], mut image: DisjointSlice<Rgba, Runtime2DIndex>) {
        if let Some(idx) = thread::index_2d_runtime(&image) {
            let dim: f32 = image.row_width() as f32;
            let x: u32 = idx.col() as u32;
            let y: u32 = idx.row() as u32;

            let ox: f32 = x as f32 - dim / 2.0f32;
            let oy: f32 = y as f32 - dim / 2.0f32;

            let mut r: f32 = 0.0f32;
            let mut g: f32 = 0.0f32;
            let mut b: f32 = 0.0f32;
            let mut maxz: f32 = -99999.0f32;

            for i in 0..20usize {
                let sphere_radius: f32 = spheres[i * 7 + 3];
                let dx: f32 = ox - spheres[i * 7 + 4];
                let dy: f32 = oy - spheres[i * 7 + 5];
                let mut n: f32 = 0.0f32;
                let t: f32;

                if (dx * dx + dy * dy) < (sphere_radius * sphere_radius) {
                    let dz: f32 = (sphere_radius * sphere_radius - dx * dx - dy * dy).sqrt();
                    n = dz / (sphere_radius * sphere_radius).sqrt();
                    t = dz + spheres[i * 7 + 6];
                } else {
                    t = -99999.0f32;
                }

                if t > maxz {
                    let fscale: f32 = n;
                    r = spheres[i * 7 + 0] * fscale;
                    g = spheres[i * 7 + 1] * fscale;
                    b = spheres[i * 7 + 2] * fscale;
                    maxz = t;
                }
            }

            if let Some(px) = image.get_mut(idx) {
                *px = Rgba([r * 255.0, g * 255.0, b * 255.0, 255.0]);
            }
        }
    }
}

fn main() {
    let dim: usize = std::env::args()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(1000);

    let spheres = generate_spheres(dim);
    let img_data: Vec<Rgba> = vec![Rgba([0.0; 4]); dim * dim];

    let block: u32 = 16;
    let grid = (dim as u32 + block - 1) / block;

    let start = Instant::now();

    let ctx = CudaContext::new(0).expect("Failed to create CUDA context");
    let stream = ctx.default_stream();

    let spheres_buf = DeviceBuffer::from_host(&stream, &spheres).expect("H2D upload");
    let mut image = DeviceBuffer::from_host(&stream, &img_data).expect("H2D upload");
    let module = kernels::load(&ctx).expect("Failed to load embedded CUDA module");

    // SAFETY: 2D launch of 16x16 blocks over a dim x dim image; every thread
    // resolves its own (row, col) pixel through the slice's witness, in-grid
    // threads beyond the image mint no witness.
    unsafe {
        module.raytracing(
            &stream,
            LaunchConfig {
                grid_dim: (grid, grid, 1),
                block_dim: (block, block, 1),
                shared_mem_bytes: 0,
            },
            &spheres_buf,
            cuda_host::RowWidth::new(&mut image, dim as u32),
        )
    }
    .expect("Kernel launch failed");

    let result = image.to_host_vec(&stream).expect("D2H readback");

    let elapsed = start.elapsed();
    println!(
        "[raytracer] elapsed: {:.3} ms",
        elapsed.as_secs_f64() * 1000.0
    );

    // Light sanity check so a silently-failed launch can't masquerade as a
    // fast run: every pixel must have been written (alpha = 255).
    let unwritten = result.iter().filter(|px| px.0[3] != 255.0).count();
    if unwritten != 0 {
        eprintln!("ERROR: {unwritten} of {} pixels were never written", result.len());
        std::process::exit(1);
    }
}
